export const METHODS = Object.keys(catalog);
export function getLevel(method, difficulty = 'F') {
  if (!catalog[method]) throw new Error(`Método desconhecido: ${method}`);
  const l = catalog[method](difficulty);
  let formula = l.formula || '', metric = l.criterion === 'width' ? 'largura do intervalo / 2' : l.criterion === 'widthResidual' ? 'máximo entre largura/2 e |f(x)|' : l.criterion === 'residual' ? 'resíduo' : l.criterion === 'delta' ? '|xₖ−xₖ₋₁|' : 'erro absoluto';
  if (l.kind === 'float') metric = l.scenario === 'readings' ? 'erro acumulado das 100 leituras' : 'erro relativo';
  if (l.kind === 'integral') { const f = method === 'trapezio' ? (difficulty === 'M' ? 'sen x' : 'x²') : method === 'simpson13' ? ({ F: 'x²', M: 'sen x', D: '√x' })[difficulty] : difficulty === 'D' ? '1/(1+400(x−0,5)²)' : 'sen x'; formula = `∫ de ${l.a.toPrecision(5)} a ${l.b.toPrecision(5)} de ${f} dx`; if (l.uCurve) metric = 'excesso relativo do modelo E(h) sobre seu mínimo'; }
  if (l.kind === 'ode') formula = `y′=${-l.lambda}y; y(0)=${l.y0}; até t=${l.end}`;
  if (l.kind === 'linear') { formula = `A·x=b · máquina ${l.decimals ? l.decimals + ' casas decimais' : l.digits + ' algarismos significativos'}`; if (l.criterion !== 'residual') metric = '‖x−x*‖∞'; }
  if (l.kind === 'fit') { formula = l.exponential ? 'y=a·exp(bx)' : l.degree === 2 ? 'y=a+bx+cx²; centralização t=x−1005' : 'y=a+bx'; metric = 'maior erro dos coeficientes'; }
  if (l.kind === 'spline') { formula = 'Nós: ' + l.xs.map((x, i) => `(${x};${(l.ys?.[i] ?? l.f(x)).toPrecision(5)})`).join(', '); metric = l.f ? 'erro máximo da curva (1001 amostras)' : 'erro máximo das curvaturas'; }
  if (l.kind === 'interpolation') { formula = l.query == null ? 'f(x)=1/(1+25x²), −1≤x≤1; até 11 nós' : `Interpolar em x=${l.query.toPrecision(6)}; ${l.xs.length} leituras iniciais`; metric = l.query == null ? 'erro máximo da curva (1001 amostras)' : 'erro no ponto consultado e nos dados fornecidos'; }
  return { ...l, id: `${method}-${difficulty}`, method, difficulty, relics: l.relics || [], timeMax: 300, mission: l.mission || `Estabilize ${l.name}. Cada operação consome energia; observe o erro e escolha as ferramentas.`, metric, formula, tools: l.tools || [method] };
}
export function bossLevels(id) {
  const specs = { chefe0: [['cancelamento', 'M'], ['overflow', 'D']], chefe1: [['bissecao', 'D'], ['newton', 'D'], ['pontoFixo', 'D']], chefe2: [['gauss', 'D'], ['pivoteamento', 'D'], ['seidel', 'D']], chefe3: [['lagrange', 'D'], ['spline', 'D'], ['minimosQuadrados', 'D']], chefe4: [['simpson38', 'D'], ['rk4', 'D'], ['euler', 'D']], final: [['lu', 'D'], ['newton', 'M'], ['rk4', 'D']] };
  const levels = specs[id].map(([m, n]) => getLevel(m, n));
  if (id === 'chefe0') levels.push({ ...getLevel('overflow', 'D'), id: 'kahan-D', scenario: 'sum', name: 'Dígitos Perdidos', target: 1.001, relics: ['kahan'], mission: 'Some 1 e dez mil parcelas de 10⁻⁷ em float32. Inverta a ordem ou use a soma compensada de Kahan.', tau: 1e-6 });
  if (id === 'chefe4') levels[2] = { ...levels[2], h: .05, forceH: .05 };
  return { id, name: ({ chefe0: 'O Overflow', chefe1: 'A Hidra das Raízes', chefe2: 'O Guardião Hilbert', chefe3: 'O Colosso de Runge', chefe4: 'O Tsunami Rígido', final: 'Colapso da Usina' })[id], levels, battery: ({ chefe0: 30, chefe1: 60, chefe2: 100, chefe3: 70, chefe4: 190, final: 140 })[id] };
}
